int leastInterval(const vector<char>& tasks, int n) {
    int cnt[26] = {0}, maxCount = 0, numMax = 0;
    for (char t : tasks) maxCount = max(maxCount, ++cnt[t - 'A']);
    for (int c : cnt) if (c == maxCount) ++numMax;
    return (maxCount - 1) * (n + 1) + numMax;
}

