bool canJump(const vector<int>& a) {
    int goal = (int)a.size() - 1;
    for (int i = goal - 1; i >= 0; --i)
        if (i + a[i] >= goal) goal = i;
    return goal == 0;
}

long long taskSchedulerII(const vector<int>& tasks, int space) {
    unordered_map<int, long long> nextOk;
    long long day = 0;
    for (int t : tasks) {
        ++day;
        auto it = nextOk.find(t);
        if (it != nextOk.end() && day < it->second) day = it->second;
        nextOk[t] = day + space + 1;
    }
    return day;
}

def can_complete_circuit(gas, cost):
    total = tank = start = 0
    for i, (g, c) in enumerate(zip(gas, cost)):
        total += g - c
        tank += g - c
        if tank < 0:
            start, tank = i + 1, 0
    return start if total >= 0 else -1

long long candy(const vector<int>& r) {
    int n = r.size();
    if (n == 0) return 0;
    long long total = 1;
    int up = 0, down = 0, peak = 0;
    for (int i = 1; i < n; ++i) {
        if (r[i] > r[i - 1]) {
            down = 0; ++up; peak = up;
            total += 1 + up;
        } else if (r[i] == r[i - 1]) {
            up = down = peak = 0;
            total += 1;
        } else {
            up = 0; ++down;
            total += down + (down > peak ? 1 : 0);
        }
    }
    return total;
}

