string longestDiverseString(int a, int b, int c) {
    priority_queue<pair<int, char>> pq;
    if (a) pq.push({a, 'a'});
    if (b) pq.push({b, 'b'});
    if (c) pq.push({c, 'c'});
    string s;
    while (!pq.empty()) {
        auto [n1, c1] = pq.top(); pq.pop();
        int L = s.size();
        if (L >= 2 && s[L - 1] == c1 && s[L - 2] == c1) {
            if (pq.empty()) break;
            auto [n2, c2] = pq.top(); pq.pop();
            s += c2;
            if (--n2) pq.push({n2, c2});
            pq.push({n1, c1});
        } else {
            s += c1;
            if (--n1) pq.push({n1, c1});
        }
    }
    return s;
}

def remove_digit(number, digit):
    last = -1
    for i, ch in enumerate(number):
        if ch == digit:
            last = i
            if i + 1 < len(number) and number[i + 1] > ch:
                return number[:i] + number[i + 1:]
    return number[:last] + number[last + 1:]

