int minOperations(vector<int> a, vector<int> b) {
    long long sa = accumulate(a.begin(), a.end(), 0LL);
    long long sb = accumulate(b.begin(), b.end(), 0LL);
    if (sa > sb) { swap(a, b); swap(sa, sb); }
    if (6LL * a.size() < (long long)b.size()) return -1;
    long long diff = sb - sa;
    int cnt[6] = {};
    for (int x : a) cnt[6 - x]++;
    for (int x : b) cnt[x - 1]++;
    int ops = 0;
    for (int g = 5; g >= 1 && diff > 0; --g) {
        while (cnt[g] > 0 && diff > 0) { diff -= g; --cnt[g]; ++ops; }
    }
    return ops;
}

