def remove_k_digits(num, k):
    st = []
    for d in num:
        while k and st and st[-1] > d:
            st.pop()
            k -= 1
        st.append(d)
    if k:
        st = st[:-k]
    return ''.join(st).lstrip('0') or '0'

string removeDuplicateLetters(const string& s) {
    array<int, 26> last{}; array<bool, 26> in{};
    for (int i = 0; i < (int)s.size(); ++i) last[s[i] - 'a'] = i;
    string st;
    for (int i = 0; i < (int)s.size(); ++i) {
        char c = s[i];
        if (in[c - 'a']) continue;
        while (!st.empty() && st.back() > c && last[st.back() - 'a'] > i) {
            in[st.back() - 'a'] = false; st.pop_back();
        }
        st.push_back(c); in[c - 'a'] = true;
    }
    return st;
}

string reorganizeString(const string& s) {
    int n = s.size();
    array<int, 26> cnt{};
    for (char c : s) cnt[c - 'a']++;
    int m = max_element(cnt.begin(), cnt.end()) - cnt.begin();
    if (cnt[m] > (n + 1) / 2) return "";
    string r(n, ' ');
    int idx = 0;
    auto place = [&](int c) {
        while (cnt[c] > 0) {
            if (idx >= n) idx = 1;
            r[idx] = char('a' + c); idx += 2; --cnt[c];
        }
    };
    place(m);
    for (int c = 0; c < 26; ++c) place(c);
    return r;
}

int minTaps(int n, const vector<int>& ranges) {
    vector<int> reach(n + 1, 0);
    for (int i = 0; i <= n; ++i) {
        int l = max(0, i - ranges[i]), r = min(n, i + ranges[i]);
        reach[l] = max(reach[l], r);
    }
    int taps = 0, curEnd = 0, far = 0;
    for (int i = 0; i < n; ++i) {
        far = max(far, reach[i]);
        if (i == curEnd) {
            if (far <= i) return -1;
            ++taps; curEnd = far;
        }
    }
    return taps;
}

