def break_palindrome(p):
    n = len(p)
    if n == 1:
        return ""
    for i in range(n // 2):
        if p[i] != 'a':
            return p[:i] + 'a' + p[i + 1:]
    return p[:-1] + 'b'

vector<int> prevPermOpt1(vector<int> a) {
    int n = a.size(), i = n - 2;
    while (i >= 0 && a[i] <= a[i + 1]) --i;
    if (i < 0) return a;
    int j = n - 1;
    while (a[j] >= a[i]) --j;
    while (j - 1 > i && a[j - 1] == a[j]) --j;
    swap(a[i], a[j]);
    return a;
}

string makeLargestSpecial(const string& s) {
    vector<string> parts;
    int bal = 0, start = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        bal += (s[i] == '1') ? 1 : -1;
        if (bal == 0) {
            parts.push_back("1" + makeLargestSpecial(s.substr(start + 1, i - start - 1)) + "0");
            start = i + 1;
        }
    }
    sort(parts.begin(), parts.end(), greater<string>());
    string res;
    for (auto& p : parts) res += p;
    return res;
}

#include <string>

std::string intToRoman(int num) {                   // 1 <= num <= 3999
  // The 13 "coins", including the six subtractive pairs, from large to small.
  static const int vals[] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
  static const char* syms[] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL",
                               "X", "IX", "V", "IV", "I"};
  std::string out;
  for (int i = 0; i < 13 && num > 0; ++i)
    while (num >= vals[i]) {                        // greedy: take the largest coin that fits
      out += syms[i];
      num -= vals[i];
    }
  return out;
}
